-- Pojok Literasi — the article shelf and what each reader did with it.
-- Paste this once into the Supabase SQL editor (this repo has no migration
-- runner, see lib/supabase.js). Safe to re-run: the article rows are
-- upserted, so a corrected script replaces the text without touching reads.
--
-- WHY ARTICLES ARE A TABLE AND NOT CONSTANTS. Oracle's brief (PROMPT-pojok-
-- literasi.md §7) shipped them as JS by OTA. Rheza, 9 Okt 2026: a posting
-- panel is coming later, and until then he sends scripts by chat. A table
-- means a new article is a row, not a build — and the panel, when it comes,
-- writes to this same table. The 69 v0 scripts below come from
-- pojok-literasi-konten-v0.md (modwiz-app root) word for word; the parser that
-- produced them never retypes a sentence.
--
-- ACCESS IS DECIDED HERE, NOT IN THE APP. The Edge Function (supabase/
-- functions/literasi) serves a locked article as its first slide only, unless
-- the caller has unlocked it (user_unlocks, product_id 'literasi:<id>') or
-- is_privilege() says yes. The app never holds text it may not show.

create table if not exists literasi_articles (
  id           text primary key,            -- 'R-04': category letter + number, the script's own ids
  category     text not null,               -- featured | tutorial | realitas | mandala | jurnal | audio
  title        text not null,
  access       text not null default 'free',-- 'free' | 'souls'
  price        integer,                     -- 5 or 10 when access = 'souls' (LITERASI_PRICE standard / deep)
  source       text,                        -- Oracle's provenance line; never shown to readers
  slides       jsonb not null,              -- [{kind:'hook'|'wow'|'aha'|'coba'|'cta', text, cta?:{label}}]
  slug         text,                        -- public address: modwizmastery.com/literasi/<slug> (sql/literasi-v2.sql fills it)
  slides_v2    jsonb,                       -- reader-v2 script {lead, accent, long, slides}; null = old reader
  featured     boolean not null default false,
  status       text not null default 'published', -- 'draft' | 'published'
  sort         integer not null default 0,  -- shelf order inside a category
  published_at timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);
create index if not exists literasi_articles_shelf_idx on literasi_articles (status, category, sort);
alter table literasi_articles enable row level security;

-- One row per (reader, article): read, bookmarked, liked, shared — four facts
-- about one pairing, so one table rather than the brief's three. A column
-- that is null simply has not happened yet.
create table if not exists literasi_user_articles (
  wp_user_id    bigint not null,
  article_id    text not null references literasi_articles (id),
  read_at       timestamptz,                -- first time the CTA slide was reached
  bookmarked_at timestamptz,
  liked_at      timestamptz,
  shared_at     timestamptz,
  updated_at    timestamptz not null default now(),
  primary key (wp_user_id, article_id)
);
create index if not exists literasi_user_articles_user_idx on literasi_user_articles (wp_user_id);
create index if not exists literasi_user_articles_article_idx on literasi_user_articles (article_id);
alter table literasi_user_articles enable row level security;

-- The counters under the reader's buttons (Rheza, 9 Okt: every button shows a
-- number). Counted on read; the shelf is small enough that a view is fine.
-- security_invoker: the view reads with the CALLER's rights, not its creator's
-- (Supabase advisor 'Security Definer View', 9 Okt 2026). The Edge Function
-- reads it with the service role either way; this only closes the hole for
-- anyone else who could reach the view.
create or replace view literasi_article_counts with (security_invoker = on) as
  select article_id,
         count(liked_at)      as likes,
         count(bookmarked_at) as bookmarks,
         count(shared_at)     as shares,
         count(read_at)       as reads
  from literasi_user_articles
  group by article_id;

on conflict (id) do update set
  category = excluded.category, title = excluded.title, access = excluded.access, price = excluded.price,
  source = excluded.source, slides = excluded.slides, featured = excluded.featured, sort = excluded.sort,
  updated_at = now();
